use vstd::prelude::*;

verus! {
    /// Given two non‐empty vectors x and y of f32, build the two
    /// Cartesian‐mesh grids:
    ///   mx[i][j] = x[j]
    ///   my[i][j] = y[i]
    fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
        requires
            // problem statement assumes non‐empty inputs
            x.len() >= 1,
            y.len() >= 1,
        ensures
        {
            let (mx, my) = result;
            // dimensions match
            mx.len() == y.len() &&
            my.len() == y.len() &&
            // for every valid (i,j), mx[i][j] == x[j] and my[i][j] == y[i]
            forall |i: usize| i < y.len() ==>
                mx[i].len() == x.len() &&
                my[i].len() == x.len() &&
                forall |j: usize| j < x.len() ==>
                    mx[i][j] == x[j] &&
                    my[i][j] == y[i]
        }
    {
        let mut mx: Vec<Vec<f32>> = Vec::with_capacity(y.len());
        let mut my: Vec<Vec<f32>> = Vec::with_capacity(y.len());
        let mut i: usize = 0;
        // outer loop over rows
        while i < y.len()
            invariant
                i <= y.len(),
                mx.len() == i,
                my.len() == i,
                // all already‐built rows satisfy the spec
                forall |k: usize| k < i ==>
                    mx[k].len() == x.len() &&
                    my[k].len() == x.len() &&
                    forall |j: usize| j < x.len() ==>
                        mx[k][j] == x[j] &&
                        my[k][j] == y[k],
            decreases y.len() - i,
        {
            // build row i
            let mut row_x: Vec<f32> = Vec::with_capacity(x.len());
            let mut row_y: Vec<f32> = Vec::with_capacity(x.len());
            let mut j: usize = 0;
            // inner loop over columns
            while j < x.len()
                invariant
                    j <= x.len(),
                    row_x.len() == j,
                    row_y.len() == j,
                    // the first j entries are as desired
                    forall |k: usize| k < j ==>
                        row_x[k] == x[k] &&
                        row_y[k] == y[i],
                decreases x.len() - j,
            {
                row_x.push(x[j]);
                row_y.push(y[i]);
                j += 1;
            }
            // now both rows have length x.len()
            assert(row_x.len() == x.len());
            assert(row_y.len() == x.len());
            mx.push(row_x);
            my.push(row_y);
            i += 1;
        }
        (mx, my)
    }
}

fn main() {
    // example run (not verified)
    let xv = vec![1.0_f32, 2.0, 3.0];
    let yv = vec![10.0_f32, 20.0];
    let (mx, my) = meshgrid(xv, yv);
    // mx == [[1,2,3],[1,2,3]]
    // my == [[10,10,10],[20,20,20]]
    println!("{:?}\n{:?}", mx, my);
}